// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 blockNum) public {
        vm.assume(amount < 10 ether);
        vm.assume(blockNum > 0);
        address sender = address(0x1234);
        vm.deal(sender, amount);
        vm.roll(blockNum);
        vm.warp(1);
        uint256 balBefore = address(c).balance;
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}("");
        if (!success || blockNum % 15 != 0) {
            assertEq(address(c).balance, balBefore, "balance should not decrease when transfer did not happen");
        }
    }
}
